/* Shared layout of the Z80 sound driver (src/z80/musdrv.c) and the 68000
 * side (src/music.c): Z80 RAM addresses, the table image the 68000 copies in
 * at start-up (generated by tools/sound/music.py) and the mailbox. */
#ifndef MUSDRV_H
#define MUSDRV_H

#define Z_TABLES     0x1D00      /* table image (patches, squares), MUS_TABLES_SIZE bytes */
#define Z_MAILBOX    0x1F00      /* stack grows down from here */

/* table image */
#define ZT_PATCH     0           /* 16 x 10: fb/alg, carrier mask, DT/MUL x4, TL x4 (OP1..OP4) */
#define ZT_SQUARE    160         /* 16: waveform is a square the PSG plays exactly */
#define MUS_TABLES_SIZE 176

/* the stream blob in ROM starts with 32 track entries of TR_SIZE bytes:
 * +0 stream offset from the blob start (3 bytes, big-endian), +3 loop offset
 * (3, big-endian), +6 frames (2, little-endian), +8 loop frame (2,
 * little-endian, FFFFh none), +10 voices used, +11 flags (bit 0: request
 * cleared at start), +12 voices[8], +20 detuned partner of each virtual voice
 * in this track, two per byte (low nibble first, Fh none) [4] */
#define TR_SIZE 24
#define TR_OFF 0
#define TR_LOOPOFF 3
#define TR_FRAMES 6
#define TR_LOOP 8
#define TR_NV 10
#define TR_FLAGS 11
#define TR_VOICES 12
#define TR_PARTNER 20

/* mailbox (offsets from Z_MAILBOX) */
#define MB_REQ       0x00        /* [32] request levels 85h..A4h (68000 writes; Z80 clears) */
#define MB_CLR       0x20        /* [4] bit n: the Z80 cleared request n (68000 acknowledges) */
#define MB_STAT      0x24        /* [2] bit n: request 86h+n playing */
#define MB_ALIVE     0x26        /* Z80 update counter */
#define MB_CMD       0x27        /* 1: stop everything (Z80 clears it) */
#define MB_GO        0x28        /* 68000 vertical interrupt: its count (the tempo) */
#define MB_DONE      0x2F        /* 68000 game loop: the count again once this frame's DMA is over */
#define MB_PROTECT   0x29        /* SGDK bus protection signal (DMA in progress) */
#define MB_BASE      0x2A        /* blob address: 68000 bank (2, LE), offset in the bank (2, LE) */
#define MB_PAL       0x2E        /* 1: 50 Hz interrupts, 6 updates per 5 */
#define MB_DBG       0x30        /* test hooks: on, wave, psg, mask, custom, fmfirst, fb (2 LE), period (2 LE), patch[10] */
#define MB_DBG_SIZE  20
#define MB_INFO      0x48        /* [8] Z80 statistics (debug) */
#define MB_LOG       0x50        /* test hook: nonzero = log chip writes to Z_LOG */
#define MB_LOGN      0x51        /* entries ever logged (2, LE); ring slot = count & (Z_LOG_MAX - 1) */
#define Z_LOG        0x1400      /* log: [port 0/2 (YM part I/II) or FFh (PSG), register, value] */
#define Z_LOG_MAX    512

#define MUS_FIRST 0x85
#define MUS_TRACKS 32
#endif
